function slackToPlain(t) {
  return String(t ?? '')
    .replace(/<(https?:[^|>]+)\|[^>]*>/g, '$1')
    .replace(/<(https?:[^>]+)>/g, '$1')
    .replace(/<mailto:([^|>]+)\|[^>]*>/g, '$1')
    .replace(/<@[A-Z0-9]+(?:\|[^>]*)?>/g, '')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&')
    .trim();
}

// One place that turns the Slack reply into the Japanese text, the customer's language, and the data the translation needs.
const row = $input.first().json;
const msg = $('Slack message').first().json;
const settings = $('Translation settings').first().json;
const ja_text = slackToPlain(msg.text);
if (!ja_text) return [];
const language = row.language || 'ja';
return [{ json: {
  line_user_id: row.line_user_id,
  language,
  language_name: row.language_name || 'Japanese',
  needs_translation: language !== 'ja',
  ja_text,
  tone: settings.tone,
  glossary: settings.glossary,
  thread_ts: msg.thread_ts,
  reply_ts: msg.ts,
} }];

// Checks that numbers, URLs and email addresses of the Japanese message survive in the translation.
// It looks at the digits as written, so it errs on the side of stopping (for example "15:00" -> "3 PM" is stopped).
function checkTranslation(ja, tr) {
  const nfkc = (s) => String(s ?? '').normalize('NFKC');
  const src = nfkc(ja);
  const dst = nfkc(tr);
  const problems = [];
  const nums = (s) => s.replace(/(?<=\d),(?=\d{3}(?!\d))/g, '').match(/\d+/g) ?? [];
  const count = (arr) => arr.reduce((m, x) => ((m[x] = (m[x] || 0) + 1), m), {});
  const cs = count(nums(src));
  const cd = count(nums(dst));
  const missing = Object.keys(cs).filter((k) => (cd[k] || 0) < cs[k]);
  if (missing.length) problems.push('numbers missing in the translation: ' + missing.join(', '));
  const trimEnd = (u) => u.replace(/[)\]、。，．,.!?！？」』）]+$/g, '');
  for (const re of [/https?:\/\/[^\s<>"]+/g, /[\w.+-]+@[\w-]+(?:\.[\w-]+)+/g]) {
    for (const m of src.match(re) ?? []) {
      const u = trimEnd(m);
      if (!dst.includes(u)) problems.push('missing in the translation: ' + u);
    }
  }
  if (!dst.trim()) problems.push('the translation is empty');
  const kana = (dst.match(/[぀-ヿ]/g) ?? []).length;
  if (kana > dst.length * 0.3) problems.push('the translation still looks Japanese');
  return problems;
}

const base = $('Prepare reply').first().json;
let translation = '', reason = '';
try {
  const rawText = $json.content?.[0]?.text ?? $json.text;
  // Claude has no JSON mode, so it may wrap the JSON in a code fence. Strip it before parsing.
  const t = String(rawText ?? '').replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
  translation = String(JSON.parse(t).translation ?? '').trim();
} catch (e) { reason = 'The AI output could not be read'; }
if (!reason) {
  const problems = checkTranslation(base.ja_text, translation);
  if (problems.length) reason = problems.join('; ');
}
return [{ json: { ...base, translation, translation_ok: !reason, reason } }];

const base = $('Check translation').first().json;
// The back-translation comes from a second call that never saw the Japanese original, so it cannot just copy it.
const back = String($json.content?.[0]?.text ?? $json.text ?? '').trim() || '(back-translation unavailable)';
return [{ json: { ...base, send_text: base.translation, back_translation: back } }];

const ev = $('Current event').first().json;
const row = $('Find thread').first().json;
const cfg = $('Config').first().json;
const prev = { code: row.language || '', name: row.language_name || '' };
let o = {};
try {
  const rawText = $json.content?.[0]?.text ?? $json.text;
  // Claude has no JSON mode, so it may wrap the JSON in a code fence. Strip it before parsing.
  const t = String(rawText ?? '').replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
  o = JSON.parse(t);
} catch (e) { o = {}; }
const confidence = Number(o.confidence);
let code = String(o.language || '').trim();
let name = String(o.language_name || '').trim();
// A short or unclear message ("OK", "?", an emoji) must not change the language we already know.
let uncertain = false;
if (!code || !(confidence >= cfg.low_confidence)) {
  if (prev.code) { code = prev.code; name = prev.name; }
  else { uncertain = true; code = ''; name = ''; }
}
const original = String(ev.text ?? '').trim();
const ja = String(o.ja ?? '').trim() || (code === 'ja' ? original : '(could not be translated)');
const translated = !!String(o.ja ?? '').trim() || code === 'ja';
let ack = String(o.ack ?? '').trim() || cfg.acknowledgment_ja;
// If the language is unknown, answer in Japanese and English.
if (uncertain) ack = cfg.acknowledgment_ja + '\n\n' + cfg.acknowledgment_en;
const lines = [];
if (uncertain) lines.push('❓ The language could not be detected. Original text and a Japanese attempt:');
else if (code !== 'ja') lines.push('🌐 ' + name + ' (' + code + ')');
lines.push('📩 ' + original);
if (code !== 'ja') lines.push('🇯🇵 ' + ja);
return [{ json: {
  language: code, language_name: name, uncertain, ja_text: ja, original, ack_text: ack,
  store_inquiry: translated ? ja : String(row.last_inquiry ?? ''),
  slack_text: lines.join("\n"),
  store_language: uncertain ? (prev.code || "") : code,
  store_language_name: uncertain ? (prev.name || "") : name,
} }];
